   325  static void
   326  ExtensionObject_deleteMembers(UA_ExtensionObject *p, const UA_DataType *_) {
   327      switch(p->encoding) {
   328      case UA_EXTENSIONOBJECT_ENCODED_NOBODY:
   329      case UA_EXTENSIONOBJECT_ENCODED_BYTESTRING:
   330      case UA_EXTENSIONOBJECT_ENCODED_XML:
   331          NodeId_deleteMembers(&p->content.encoded.typeId, NULL);
   332          String_deleteMembers(&p->content.encoded.body, NULL);
   333          break;
   334      case UA_EXTENSIONOBJECT_DECODED:
   335          if(p->content.decoded.data)
   336              UA_delete(p->content.decoded.data, p->content.decoded.type);
   337          break;
   338      default:
   339          break;
   340      }
   341  }
