   386  static UA_StatusCode
   387  Variant_copy(UA_Variant const *src, UA_Variant *dst, const UA_DataType *_) {
   388      size_t length = src->arrayLength;
   389      if(UA_Variant_isScalar(src))
   390          length = 1;
---
   525  Array_decodeBinary(void *UA_RESTRICT *UA_RESTRICT dst,
   526                     size_t *out_length, const UA_DataType *type) {
   527      /* Decode the length */
   528      i32 signed_length;
   529      status ret = Int32_decodeBinary(&signed_length);
   530      if(ret != UA_STATUSCODE_GOOD)
   531          return ret;
   532
   533      /* Return early for empty arrays */
   534      if(signed_length <= 0) {
   535          *out_length = 0;
   536          if(signed_length < 0)
   537              *dst = NULL;
   538          else
   539              *dst = UA_EMPTY_ARRAY_SENTINEL;
   540          return UA_STATUSCODE_GOOD;
   541      }
   542
   543      /* Filter out arrays that can obviously not be decoded, because the message
   544       * is too small for the array length. This prevents the allocation of very
   545       * long arrays for bogus messages.*/
   546      size_t length = (size_t)signed_length;
   547      if(g_pos + ((type->memSize * length) / 32) > g_end)
   548          return UA_STATUSCODE_BADDECODINGERROR;
   549
   550      /* Allocate memory */
   551      *dst = UA_calloc(length, type->memSize);
   552      if(!*dst)
   553          return UA_STATUSCODE_BADOUTOFMEMORY;
   554
   555      if(type->overlayable) {
   556          /* memcpy overlayable array */
   557          if(g_end < g_pos + (type->memSize * length)) {
   558              UA_free(*dst);
   559              *dst = NULL;
   560              return UA_STATUSCODE_BADDECODINGERROR;
   561          }
   562          memcpy(*dst, g_pos, type->memSize * length);
   563          g_pos += type->memSize * length;
   564      } else {
   565          /* Decode array members */
   566          uintptr_t ptr = (uintptr_t)*dst;
   567          size_t decode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   568          for(size_t i = 0; i < length; ++i) {
   569              ret = decodeBinaryJumpTable[decode_index]((void*)ptr, type);
   570              if(ret != UA_STATUSCODE_GOOD) {
   571                  // +1 because last element is also already initialized
   572                  UA_Array_delete(*dst, i+1, type);
   573                  *dst = NULL;
   574                  return ret;
   575              }
   576              ptr += type->memSize;
   577          }
   578      }
   579      *out_length = length;
   580      return UA_STATUSCODE_GOOD;
   581  }
